-- ESQUEMA DE PRUEBA (PostgreSQL puro). Replica la FORMA de las tablas reales leída en modo solo lectura el 2026-11-01
-- (information_schema / pg_indexes / pg_policies del proyecto Supabase) para poder probar las propuestas de supabase/pending.
-- NO es Supabase: auth.users, auth.uid() y los roles son SUSTITUTOS mínimos. No valida PostgREST, Auth ni Storage.
create role anon nologin; create role authenticated nologin; create role service_role nologin bypassrls;
create schema auth;
create table auth.users (id uuid primary key);
create function auth.uid() returns uuid language sql stable as $$ select coalesce(nullif(current_setting('request.jwt.claim.sub', true), ''), (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'sub'))::uuid $$;
grant usage on schema auth, public to anon, authenticated, service_role;
grant execute on function auth.uid() to anon, authenticated, service_role;
alter default privileges in schema public grant all on tables to anon, authenticated, service_role;
alter default privileges in schema public grant all on sequences to anon, authenticated, service_role;
-- Supabase concede EXECUTE por defecto a estos roles en funciones nuevas del esquema public (las migraciones lo revocan donde procede).
alter default privileges in schema public grant execute on functions to anon, authenticated, service_role;

create table public.projects (
  id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, name text not null,
  description text, status text not null default 'draft', target_platforms text[] not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.assets (
  id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, project_id uuid references public.projects(id) on delete cascade,
  asset_type text not null, storage_path text, source_provider text, source_url text, license_status text not null default 'unknown', provenance jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table public.scripts (
  id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, project_id uuid not null references public.projects(id) on delete cascade,
  source_opportunity_id uuid, parent_id uuid references public.scripts(id) on delete set null, version integer not null default 1 check (version > 0), title text not null check (char_length(title) between 1 and 200),
  status text not null default 'draft', idea text, brief text, hook text, cta text, sections jsonb not null default '[]'::jsonb, review_notes text,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (project_id, version));
create table public.storyboards (
  id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, project_id uuid not null references public.projects(id) on delete cascade,
  title text not null, aspect_ratio text not null default '16:9', version integer not null default 1, created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  script_id uuid references public.scripts(id) on delete set null);
create index storyboards_script_idx on public.storyboards (script_id);
create table public.scenes (
  id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, storyboard_id uuid not null references public.storyboards(id) on delete cascade,
  position integer not null, duration_ms integer not null default 5000, narration text, visual_prompt text, video_prompt text, ambient_prompt text, metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(), unique (storyboard_id, position));
create table public.generation_spend (
  id bigint generated by default as identity primary key, owner_id uuid not null references auth.users(id) on delete cascade, request_id text not null, provider text not null, model text not null,
  tier text not null, estimate_usd numeric(12,4) not null check (estimate_usd >= 0), created_at timestamptz not null default now(), unique (owner_id, request_id));
create index generation_spend_owner_created_idx on public.generation_spend (owner_id, created_at desc);

do $$ declare t text; begin
  foreach t in array array['projects','assets','scripts','storyboards','scenes','generation_spend'] loop execute format('alter table public.%I enable row level security', t); end loop;
end $$;
create policy projects_own on public.projects for all to authenticated using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));
create policy assets_own on public.assets for all to authenticated using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));
create policy scripts_owner_all on public.scripts for all to authenticated using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));
create policy storyboards_own on public.storyboards for all to authenticated using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));
create policy scenes_own on public.scenes for all to authenticated using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));
create policy generation_spend_owner_read on public.generation_spend for select to authenticated using (owner_id = (select auth.uid()));
-- Igual que la migración de seguridad ya aplicada: el navegador solo LEE el libro de gasto.
revoke all on public.generation_spend from anon, authenticated; grant select on public.generation_spend to authenticated;
